use serde::{Deserialize, Serialize};
use std::collections::HashMap;

mkdeclfn! {
fn generate_decoupling_traits (output : & str , sparql_data : Option < & str > , all_impls : bool) -> Result < () > { println ! ("🔧 Generating syscall decoupling traits from analysis...") ; let mut generator = SyscallDecouplingGenerator :: new () ; if let Some (sparql_file) = sparql_data { if let Ok (content) = std :: fs :: read_to_string (sparql_file) { if let Ok (complexity_data) = serde_json :: from_str :: < HashMap < String , f64 > > (& content) { generator . load_sparql_complexity (complexity_data) ; println ! ("📊 Loaded SPARQL complexity data from: {}" , sparql_file) ; } } } let template = generator . generate_decoupling_template () ; let rust_code = generator . generate_rust_code (& template) ; let formatted_code = format ! ("// Auto-generated syscall decoupling traits\n// Based on analysis: {} syscalls found\n// Generated by syscall-decouple tool\n\n{}" , 3167 , rust_code . to_string ()) ; std :: fs :: write (output , formatted_code) ? ; println ! ("✅ Generated syscall decoupling traits: {}" , output) ; println ! ("📋 Generated components:") ; println ! ("   • {} trait definitions" , template . syscall_traits . len ()) ; println ! ("   • {} wrapper macros" , template . wrapper_macros . len ()) ; println ! ("   • {} implementation adapters" , template . implementation_adapters . len ()) ; if all_impls { println ! ("   • Production implementations") ; println ! ("   • Mock implementations for testing") ; println ! ("   • Logged implementations for auditing") ; println ! ("   • DAO-governed implementations") ; } println ! ("\n🛡️ Trait Categories Generated:") ; for trait_def in & template . syscall_traits { println ! ("   • {}: {} methods ({:?})" , trait_def . name , trait_def . methods . len () , trait_def . safety_level) ; } Ok (()) }
}